def transform(grid):
    n = len(grid[0])
    center = next((j for j, v in enumerate(grid[0]) if v == 2), n // 2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if abs(c - center) == r and r <= center:
                out[r][c] = 2
            elif r >= 3 and (c - r) % 4 == center % 4 and abs(c - center) <= max(0, r - 2):
                out[r][c] = 1
    return out
